B07_IDS = ["LY-009","LY-01","LY-010","LY-011","LY-012","LY-013","LY-014","LY-015","LY-016","LY-017","LY-018","LY-019","LY-021","LY-022","LY-023","LY-024","LY-025","LY-026","LY-027","LY-028"]

def write_batch(ids, label):
    assert set(ids) <= set(P), (label, set(ids)-set(P))
    n = 0
    for cid in ids:
        d = P[cid]
        rec = {"case_id": cid, "prediction_text": d["prediction_text"], "basis": d["basis"],
               "confidence": d["conf"], "trigger": d["trig"]}
        assert set(rec) == {"case_id","prediction_text","basis","confidence","trigger"}, cid
        assert isinstance(rec["confidence"], float) and 0.0 <= rec["confidence"] <= 1.0, cid
        t = rec["trigger"]
        assert set(t) == {"changed_main","reserve_used","disputed","reason"}, cid
        assert all(isinstance(t[k], bool) for k in ("changed_main","reserve_used","disputed")), cid
        assert isinstance(t["reason"], str), cid
        with open(os.path.join(OUT, cid + ".json"), "w", encoding="utf-8") as f:
            json.dump(rec, f, ensure_ascii=False, indent=1)
        n += 1
    assert n == len(ids) == 20, (label, n)
    print(label, "written", n)

if __name__ == "__main__":
    write_batch(B07_IDS, "B07")

